/**
 * An `extra.version` the buyer can sign: one of `CIRCLE_BATCHING_VERSIONS`.
 */
type CircleBatchingVersion = (typeof CIRCLE_BATCHING_VERSIONS)[number];
/**
 * Extra fields specific to Circle Gateway batching in PaymentRequirements.
 */
interface BatchExtra {
    /** EIP-712 domain name - must be "GatewayWalletBatched" */
    name: typeof CIRCLE_BATCHING_NAME;
    /** EIP-712 domain version - one of `CIRCLE_BATCHING_VERSIONS` */
    version: CircleBatchingVersion;
    /** The GatewayWallet contract address used as verifyingContract in EIP-712 */
    verifyingContract: Address;
}
/**
 * PaymentRequirements whose `extra` is Circle Gateway batching data.
 */
type GatewayPaymentRequirements<T> = T & {
    extra: BatchExtra;
};
/**
 * Configuration for BatchFacilitatorClient.
 */
interface BatchFacilitatorConfig {
    /** Base URL of Circle Gateway. Defaults to "https://gateway-api.circle.com" */
    url?: string;
    /**
     * Additional headers merged into every outbound Gateway API request.
     * These take precedence over auth headers from `createAuthHeaders` on collision.
     */
    headers?: Record<string, string>;
    /** Optional function to create auth headers for requests */
    createAuthHeaders?: () => Promise<{
        verify: Record<string, string>;
        settle: Record<string, string>;
        supported: Record<string, string>;
    }>;
}
/**
 * Configuration for CircleFacilitatorClient.
 *
 * Authenticate with either or both of:
 * - `sellerSigner` (keyless): every request carries an EIP-712 seller proof
 *   signed by the seller destination. No Circle account needed.
 * - `apiKey` (registered): every request carries `Authorization: Bearer <apiKey>`.
 *
 * When both are set, `apiKey` is used for verify, settle, and status.
 * `claimSellerAccount` needs both, since claiming binds a keyless seller
 * account to the API key's entity.
 */
interface CircleFacilitatorConfig {
    /** Base URL of the Circle Facilitator x402 API. Defaults to `FACILITATOR_URL`. */
    url?: string;
    /** Circle API key for registered (entity) authentication. */
    apiKey?: string;
    /** Signer for keyless seller proofs. A viem account works. */
    sellerSigner?: EvmSigner;
    /**
     * Seller destination (`payTo`) proven by `sellerSigner`. Defaults to the
     * signer's address; set it when `payTo` is a contract wallet (ERC-1271).
     */
    sellerAddress?: string;
    /** Additional headers merged into every outbound Facilitator request. */
    headers?: Record<string, string>;
    /** Seller proof lifetime in seconds. Defaults to `FACILITATOR_SELLER_PROOF_TTL_SECONDS`. */
    proofTtlSeconds?: number;
}
/**
 * EIP-3009 TransferWithAuthorization message structure.
 */
interface TransferWithAuthorizationMessage {
    from: Address;
    to: Address;
    value: bigint;
    validAfter: bigint;
    validBefore: bigint;
    nonce: Hex;
}
/**
 * Generic EIP-712 signer. `verifyingContract` is optional because some
 * domains (e.g. Circle Facilitator seller proofs) are bound to a service
 * rather than a contract. A viem account satisfies this interface.
 */
interface EvmSigner {
    /** The signer's address */
    address: Address;
    /** Sign EIP-712 typed data */
    signTypedData: (params: {
        domain: {
            name: string;
            version: string;
            chainId: number;
            verifyingContract?: Address;
        };
        types: Record<string, Array<{
            name: string;
            type: string;
        }>>;
        primaryType: string;
        message: Record<string, unknown>;
    }) => Promise<Hex>;
}
/**
 * EVM signer interface for creating payment payloads.
 * `salt` is set only on the version 2 domain.
 */
interface BatchEvmSigner {
    /** The signer's address */
    address: Address;
    /** Sign EIP-712 typed data */
    signTypedData: (params: {
        domain: {
            name: string;
            version: string;
            chainId: number;
            verifyingContract: Address;
            salt?: Hex;
        };
        types: Record<string, Array<{
            name: string;
            type: string;
        }>>;
        primaryType: string;
        message: Record<string, unknown>;
    }) => Promise<Hex>;
}
/**
 * Payload structure for batching payments.
 */
interface BatchPayload {
    signature: Hex;
    authorization: {
        from: Address;
        to: Address;
        value: string;
        validAfter: string;
        validBefore: string;
        nonce: Hex;
    };
}

/**
 * Express-compatible request with payment info.
 */
interface PaymentRequest extends IncomingMessage {
    payment?: {
        /** Whether the payment was verified */
        verified: boolean;
        /** Payer's address */
        payer: string;
        /** Amount paid in smallest units */
        amount: string;
        /** Network the payment was made on */
        network: string;
        /** Token contract address of the payment */
        asset: string;
        /** Transaction hash after settlement */
        transaction?: string;
    };
    body?: unknown;
}
/**
 * Express-compatible response.
 */
interface PaymentResponse extends ServerResponse {
    json?: (data: unknown) => void;
    status?: (code: number) => PaymentResponse;
}
/**
 * Express-compatible next function.
 */
type NextFunction = (err?: unknown) => void;
/**
 * Express-compatible middleware function.
 */
type MiddlewareFunction = (req: PaymentRequest, res: PaymentResponse, next: NextFunction) => void | Promise<void>;
/**
 * A price in the units of a token, for example
 * `{ token: 'EURC', price: '0.009' }`.
 */
interface TokenPrice {
    token: TokenName;
    price: string;
}
/**
 * The price of a route. A string is a USDC price, for example `'$0.01'` or
 * `'0.01'`.
 */
type RoutePrice = string | TokenPrice;
interface PaymentMiddlewareCore {
    /** Returns middleware that requires a payment of `price`. */
    require: (price: RoutePrice) => MiddlewareFunction;
    verify: (payment: unknown) => Promise<{
        valid: boolean;
        payer?: string;
        error?: string;
    }>;
    settle: (payment: unknown) => Promise<{
        success: boolean;
        transaction?: string;
        error?: string;
        extensions?: Record<string, unknown>;
    }>;
}
/** Chainable lifecycle hook registration; see {@link GatewayMiddleware}. */
interface PaymentMiddlewareHooks<Self> {
    onProtectedRequest: (hook: ProtectedRequestHook) => Self;
    onBeforeVerify: (hook: BeforeVerifyHook) => Self;
    onAfterVerify: (hook: AfterVerifyHook) => Self;
    onVerifyFailure: (hook: OnVerifyFailureHook) => Self;
    onBeforeSettle: (hook: BeforeSettleHook) => Self;
    onAfterSettle: (hook: AfterSettleHook) => Self;
    onSettleFailure: (hook: OnSettleFailureHook) => Self;
    onVerifiedPaymentCanceled: (hook: OnVerifiedPaymentCanceledHook) => Self;
}

/**
 * Lifecycle hook types for the Circle Gateway batching SDK.
 *
 * These mirror the lifecycle hooks defined in the standard `@x402/core` SDK.
 * See https://docs.x402.org/advanced-concepts/lifecycle-hooks for the full
 * reference. The semantics implemented here match that documentation: hooks
 * receive a read-only context, drive control flow via `abort` / `skip` /
 * `recovered` return values, and a thrown hook is logged but does not break
 * the surrounding payment flow (the next hook still runs).
 */
/**
 * Minimal `PaymentPayload` shape (subset used by hook contexts).
 */
interface HookPaymentPayload {
    x402Version: number;
    payload: Record<string, unknown>;
    resource?: {
        url: string;
        description: string;
        mimeType: string;
    };
    accepted?: Record<string, unknown>;
    extensions?: Record<string, unknown>;
}
/**
 * Minimal `PaymentRequirements` shape (subset used by hook contexts).
 */
interface HookPaymentRequirements {
    scheme: string;
    network: string;
    asset: string;
    amount: string;
    payTo: string;
    maxTimeoutSeconds: number;
    extra?: Record<string, unknown>;
}
/**
 * Minimal `VerifyResponse` shape (subset used by hook contexts).
 */
interface HookVerifyResponse {
    isValid: boolean;
    invalidReason?: string;
    payer?: string;
}
/**
 * Minimal `SettleResponse` shape (subset used by hook contexts).
 */
interface HookSettleResponse {
    success: boolean;
    errorReason?: string;
    payer?: string;
    transaction: string;
    network: string;
}
interface VerifyContext {
    paymentPayload: HookPaymentPayload;
    requirements: HookPaymentRequirements;
}
interface VerifyResultContext extends VerifyContext {
    result: HookVerifyResponse;
}
interface VerifyFailureContext extends VerifyContext {
    error: Error;
}
interface SettleContext {
    paymentPayload: HookPaymentPayload;
    requirements: HookPaymentRequirements;
}
interface SettleResultContext extends SettleContext {
    result: HookSettleResponse;
}
interface SettleFailureContext extends SettleContext {
    error: Error;
}
/**
 * Reason a verified payment never reached settlement. `handler_threw` matches
 * the standard SDK's reason for "the protected handler errored".
 */
type VerifiedPaymentCancellationReason = 'handler_threw' | 'handler_failed';
interface VerifiedPaymentCanceledContext extends SettleContext {
    reason: VerifiedPaymentCancellationReason;
    error?: unknown;
    responseStatus?: number;
}
type BeforeVerifyHook = (context: VerifyContext) => Promise<void | {
    abort: true;
    reason: string;
    message?: string;
} | {
    skip: true;
    result: HookVerifyResponse;
}>;
type AfterVerifyHook = (context: VerifyResultContext) => Promise<void | {
    skipHandler: true;
    response?: {
        contentType?: string;
        body?: unknown;
    };
}>;
type OnVerifyFailureHook = (context: VerifyFailureContext) => Promise<void | {
    recovered: true;
    result: HookVerifyResponse;
}>;
type BeforeSettleHook = (context: SettleContext) => Promise<void | {
    abort: true;
    reason: string;
    message?: string;
} | {
    skip: true;
    result: HookSettleResponse;
}>;
type AfterSettleHook = (context: SettleResultContext) => Promise<void>;
type OnSettleFailureHook = (context: SettleFailureContext) => Promise<void | {
    recovered: true;
    result: HookSettleResponse;
}>;
type OnVerifiedPaymentCanceledHook = (context: VerifiedPaymentCanceledContext) => Promise<void>;
type FacilitatorBeforeVerifyHook = (context: VerifyContext) => Promise<void | {
    abort: true;
    reason: string;
}>;
type FacilitatorAfterVerifyHook = (context: VerifyResultContext) => Promise<void>;
type FacilitatorOnVerifyFailureHook = (context: VerifyFailureContext) => Promise<void | {
    recovered: true;
    result: HookVerifyResponse;
}>;
type FacilitatorBeforeSettleHook = (context: SettleContext) => Promise<void | {
    abort: true;
    reason: string;
}>;
type FacilitatorAfterSettleHook = (context: SettleResultContext) => Promise<void>;
type FacilitatorOnSettleFailureHook = (context: SettleFailureContext) => Promise<void | {
    recovered: true;
    result: HookSettleResponse;
}>;
/**
 * Minimal HTTP request descriptor passed to `onProtectedRequest`. Mirrors the
 * shape standard x402 uses, but reduced to the bits the gateway middleware
 * actually has access to.
 */
interface ProtectedRequestContext {
    /** The HTTP method (uppercase, e.g. "GET"). */
    method: string;
    /** The request path (no query string). */
    path: string;
    /** Full URL as advertised in the 402 response (may equal `path`). */
    url: string;
    /**
     * Case-insensitive header lookup. Returns `undefined` for unknown headers.
     */
    getHeader(name: string): string | undefined;
}
interface ProtectedRouteConfig {
    /** Price passed to `require(...)`. */
    price: RoutePrice;
}
type ProtectedRequestHook = (context: ProtectedRequestContext, routeConfig: ProtectedRouteConfig) => Promise<void | {
    grantAccess: true;
} | {
    abort: true;
    reason: string;
}>;
/**
 * Minimal `PaymentRequired` shape passed to client hook contexts.
 */
interface HookPaymentRequired {
    x402Version: number;
    resource?: {
        url: string;
        description: string;
        mimeType: string;
    };
    accepts: HookPaymentRequirements[];
    extensions?: Record<string, unknown>;
    error?: string;
}
interface PaymentCreationContext {
    paymentRequired: HookPaymentRequired;
    selectedRequirements: HookPaymentRequirements;
}
interface PaymentCreatedContext extends PaymentCreationContext {
    paymentPayload: HookPaymentPayload;
}
interface PaymentCreationFailureContext extends PaymentCreationContext {
    error: Error;
}
interface PaymentResponseContext {
    paymentPayload: HookPaymentPayload;
    requirements: HookPaymentRequirements;
    settleResponse?: HookSettleResponse;
    paymentRequired?: HookPaymentRequired;
    error?: Error;
}
type BeforePaymentCreationHook = (context: PaymentCreationContext) => Promise<void | {
    abort: true;
    reason: string;
}>;
type AfterPaymentCreationHook = (context: PaymentCreatedContext) => Promise<void>;
type OnPaymentCreationFailureHook = (context: PaymentCreationFailureContext) => Promise<void | {
    recovered: true;
    payload: HookPaymentPayload;
}>;
type OnPaymentResponseHook = (context: PaymentResponseContext) => Promise<void | {
    recovered: true;
}>;

